(()=>{'use strict';
const {Game,B,talentOptions,vehicleName,vehicleWeapons,upgradeIndex}=Frontline,$=id=>document.getElementById(id);
const types=['tank','bradley','artillery','littlebird'],keys=['damage','range','rate','health','speed'],labels={damage:'Урон',range:'Дальность',rate:'Скорострельность',health:'Здоровье',speed:'Скорость'},roles={littlebird:'Высокая сложность. Лёгкий вертолёт с двумя миниганами. Короткая дальность, высокая скорострельность, разгон и управление по направлению носа. Боезапас восстанавливается пассивно; доступны тепловые ловушки и 15 пар талантов.',tank:'Высокие здоровье, броня и урон. Средние скорострельность и подвижность.',bradley:'Средние здоровье, броня и урон. Высокие скорострельность и подвижность.',artillery:'Низкие здоровье, броня и подвижность. Огромный урон, медленная стрельба.'};
const builds=Object.fromEntries(types.map(t=>[t,{ranks:Object.fromEntries(keys.map(k=>[k,0])),picks:Array.from({length:15},()=>[false,false]),level:30}]));let type='tank';
const fmt=(v,d=1)=>Number.isFinite(v)?Number(v.toFixed(d)).toLocaleString('ru-RU'):'—';
function count(b){return b.picks.flat().filter(Boolean).length;}function rankCount(b){return Object.values(b.ranks).reduce((a,v)=>a+v,0);}
function valid(b){return rankCount(b)<=b.level&&count(b)<=b.level&&b.picks.every((row,i)=>!row.some(Boolean)||b.level>=i+1)&&b.picks.every((row,i)=>!row.every(Boolean)||b.level>=i+16);}
function simulate(b,base=false){const g=new Game({random:()=>.5});g.players[0]=g.makePlayer(0,type);g.structures=[];g.covers=[];g.bushes=[];g.units=[];g.players[1].enabled=false;const p=g.players[0];p.tank.x=1000;p.tank.y=700;p.tank.angle=p.tank.turret=0;g.gain(p,B.levels[b.level-1]||0);p.level=b.level;p.statPoints=b.level;p.pending=[];
 if(!base){for(const key of keys)for(let i=0;i<b.ranks[key];i++)g.command(0,{type:'statUpgrade',stat:key});for(let level=1;level<=30;level++){const row=upgradeIndex(level),selected=b.picks[row];if(!selected)continue;const choices=selected.map((v,i)=>v?i:-1).filter(i=>i>=0);const choice=level<=15?choices[0]:choices[1];if(choice!==undefined){p.pending=[level];g.command(0,{type:'upgrade',choice});}}}
 p.pending=[];p.skillState.still=$('prepared').checked?60:0;g.updatePlayer(p,0);if(type==='artillery')p.elevation=75;return {g,p};}
function stats(model){const {g,p}=model;return [['Здоровье',p.tank.max,' HP'],['Броня',p.tank.armor,''],['Скорость',p.tank.speed,' ед/с'],['Обзор',p.tank.vision/B.mapScale.unitsPerMeter,' м'],['Дальность пушки',type==='artillery'?FrontlineArtillery.rangeFor(p,B)/B.mapScale.unitsPerMeter:g.attackRange(p)/B.mapScale.unitsPerMeter,' м'],['Поворот башни',p.turnSpeed*180/Math.PI,' °/с'],['Передняя броня · талант',p.frontArmor*100,' %'],['Боковая броня · талант',p.sideArmor*100,' %'],['Задняя броня · талант',p.rearArmor*100,' %'],['Активный ремонт',p.repairRate,' HP/с'],['Подготовка ремонта',p.repairWarmup,' с']];}
function weaponStats(model,key){const {g,p}=model;p.weapon=key;p.cannon={loaded:key};p.switchLeft=0;p.tank.cd=0;if(type==='artillery')p.skillState.still=Math.max(p.skillState.still,p.skills?.arPrepare?.seconds??B.artillery.ballistics.prepareSeconds);g.shots=[];g.fire(p.tank,{kind:'ground',x:1600,y:700});const shot=g.shots[0],profile=g.profile(p.tank,{kind:'tank'}),cfg=vehicleWeapons(p)[key];return {damage:(shot?.damage??profile.damage)*(type==='littlebird'?2:1),interval:profile.interval,range:type==='artillery'&&key!=='MG'?FrontlineArtillery.rangeFor(p,B):g.attackRange(p),radius:shot?.blastRadius??cfg.radius??0,damageFactor:type==='artillery'?B.artillery.ballistics.structureDamageMultiplier*(p.skills?.arSiege?.multiplier??1):1};}
function render(){const b=builds[type];$('level').value=b.level;$('vehicleTitle').textContent=vehicleName(type);$('role').textContent=roles[type];$('budget').textContent='Очки характеристик: '+rankCount(b)+' / '+b.level+' · Таланты: '+count(b)+' / '+b.level;
 $('vehicles').innerHTML=types.map(t=>'<button data-type="'+t+'" aria-pressed="'+(t===type)+'">'+vehicleName(t)+'</button>').join('');
 $('ranks').innerHTML=keys.map(k=>'<div class="rank"><span>'+labels[k]+'</span><button data-stat="'+k+'" data-delta="-1" aria-label="Убавить '+labels[k]+'" '+(!b.ranks[k]?'disabled':'')+'>−</button><output>'+b.ranks[k]+'/6</output><button data-stat="'+k+'" data-delta="1" aria-label="Добавить '+labels[k]+'" '+(b.ranks[k]>=6||rankCount(b)>=b.level?'disabled':'')+'>+</button></div>').join('');
 const model=simulate(b),base=simulate(b,true),s=stats(model),z=stats(base);$('summary').innerHTML=s.map((v,i)=>'<div><dt>'+v[0]+'</dt><dd>'+fmt(z[i][1])+' → '+fmt(v[1])+v[2]+'</dd></div>').join('');
 const weaponLabels={ChainGun:'Два минигана (суммарно)',AP:'Бронебойный снаряд',HE:'Фугасный снаряд',MG:'Пулемёт',TOW:'TOW'};$('weapons').innerHTML=Object.keys(weaponLabels).filter(k=>vehicleWeapons(model.p)[k]).map(k=>{const v=weaponStats(model,k),q=weaponStats(base,k);return '<tr><td>'+weaponLabels[k]+'</td><td>'+fmt(q.damage)+' → '+fmt(v.damage)+'</td><td>'+fmt(q.interval,2)+' → '+fmt(v.interval,2)+' с</td><td>'+fmt(q.range/B.mapScale.unitsPerMeter)+' → '+fmt(v.range/B.mapScale.unitsPerMeter)+' м</td><td>'+(v.radius?'Радиус '+fmt(v.radius/B.mapScale.unitsPerMeter)+' м. ':'')+(type==='artillery'?'По башням/турелям '+fmt(v.damageFactor*100)+'%. ':'')+'</td></tr>';}).join('');
 const options=talentOptions(model.p);$('talents').innerHTML=options.length?options.map((row,i)=>'<section class="talent-row '+(i===14?'final':'')+'"><p>УРОВНИ '+(i+1)+' / '+(i+16)+'</p><div class="talent-pair">'+row.map((text,j)=>{const picked=b.picks[i][j],copy=structuredClone(b);copy.picks[i][j]=!picked;return '<button data-row="'+i+'" data-choice="'+j+'" aria-pressed="'+picked+'" '+(!picked&&!valid(copy)?'disabled':'')+'>'+text+'<small>'+(picked?'− Убрать талант':'+ Изучить талант')+'</small></button>';}).join('')+'</div></section>').join(''):'<p class="note">Таланты Little Bird пока не добавлены. Можно тестировать характеристики и вооружение.</p>';}
 $('vehicles').onclick=e=>{const t=e.target.closest('[data-type]')?.dataset.type;if(t){type=t;render();}};
 $('ranks').onclick=e=>{const button=e.target.closest('[data-stat]');if(!button||button.disabled)return;const b=builds[type],k=button.dataset.stat;b.ranks[k]+=Number(button.dataset.delta);render();};
 $('talents').onclick=e=>{const button=e.target.closest('[data-row]');if(!button||button.disabled)return;const b=builds[type],i=Number(button.dataset.row),j=Number(button.dataset.choice);b.picks[i][j]=!b.picks[i][j];render();};
 $('level').onchange=()=>{const b=builds[type];b.level=Math.min(30,Math.max(1,Math.trunc(Number($('level').value)||1)));for(let i=14;i>=0;i--){if(b.level<i+1)b.picks[i]=[false,false];else if(b.level<i+16&&b.picks[i].every(Boolean))b.picks[i][1]=false;}while(rankCount(b)>b.level)for(const k of [...keys].reverse())if(b.ranks[k]){b.ranks[k]--;break;}while(count(b)>b.level)for(let i=14;i>=0;i--)if(b.picks[i].some(Boolean)){b.picks[i][b.picks[i][1]?1:0]=false;break;}render();};
 $('prepared').onchange=render;$('reset').onclick=()=>{builds[type].ranks=Object.fromEntries(keys.map(k=>[k,0]));builds[type].picks=Array.from({length:15},()=>[false,false]);render();};render();
})();
